async function api(url,options={}){const headers={'X-Demo-User':user(),...(options.body?{'Content-Type':'application/json','Idempotency-Key':options.ticket||ticket()}:{})};const r=await fetch(url,{...options,headers:{...headers,...options.headers}});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Request could not be completed.');return d}
function flash(msg,error=false){$('#notice').innerHTML=`<div class="${error?'error':''}">${msg}</div>`;setTimeout(()=>$('#notice').innerHTML='',5000)}
function status(s){return `<span class="status ${s==='AVAILABLE'||['PAID','COMPLETED'].includes(s)?'':'bad'}">${label(s)}</span>`}function fmtDate(d){return String(d).slice(0,10)}
async function boot(){try{const p=await api('/api/people');state.people=p.people;const chosen=state.people.find(x=>x.id===user())||state.people.find(x=>x.id===MAYA);localStorage.setItem('gearvault-demo-user',chosen.id);$('#person').innerHTML=state.people.map(x=>`<option value="${x.id}" ${x.id===chosen.id?'selected':''}>${x.full_name} · ${label(x.role)}</option>`).join('');await load();const q=new URLSearchParams(location.search);if(q.get('checkout')==='success'&&q.get('session_id')){await api('/api/payments/confirm',{method:'POST',body:JSON.stringify({session_id:q.get('session_id')})});history.replaceState({},'',location.pathname);flash('Payment confirmed — your dates are now held.');await load();showRecords()}else if(q.get('checkout')==='cancelled'){history.replaceState({},'',location.pathname);flash('Checkout was cancelled. No dates were held.',true)}}catch(e){flash(e.message,true)}}
async function load(){const d=await api('/api/overview');Object.assign(state,d);renderNav();renderHome()}
function renderNav(){const customer=state.me.role==='customer';$('#nav').innerHTML=customer?'<a href="#catalog">Catalog</a><a href="#records" data-view="records">My rentals</a><a href="#records" data-view="records">My records</a>':'<a href="#workspace">Workspace</a><a href="#catalog">Fleet</a>';$('#heroActions').innerHTML=`<a class="btn" href="#${customer?'catalog':'workspace'}">${customer?'Browse equipment':'Open my workspace'}</a>`;document.querySelectorAll('[data-view=records]').forEach(a=>a.onclick=e=>{e.preventDefault();showRecords()})}
function renderHome(){if(state.me.role==='customer')renderCatalog();else renderWorkspace()}
function card(u){const available=u.status==='AVAILABLE';return `<article class="card" data-category="${u.category}"><div class="row between"><span class="tag">${u.asset_tag}</span>${status(u.status)}</div><h3>${u.model}</h3><div class="muted">${u.category} · ${u.location_name}</div><div class="meta"><div><div class="price">${money(u.daily_rate_cents)} <small>/ day</small></div></div><div>Deposit<br><b>${money(u.deposit_cents)}</b></div></div><div class="muted">Replacement ${money(u.replacement_value_cents)}${u.required_certification?` · Requires ${u.required_certification}`:''}</div>${available?`<button class="btn dark" data-book="${u.id}">View dates & book</button>`:'<button class="btn ghost" disabled>Not available for walk-up</button>'}</article>`}
function renderCatalog(){const cats=['All',...new Set(state.units.map(u=>u.category))];const list=state.filter==='All'?state.units:state.units.filter(u=>u.category===state.filter);$('#content').innerHTML=`<div class="section" id="catalog"><div class="section-head"><div><p class="eyebrow" style="color:var(--rust)">THE EQUIPMENT WALL</p><h2>Choose your kit</h2><p>Every card is one physical, serialized unit.</p></div><div class="filters">${cats.map(c=>`<button class="${c===state.filter?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div></div><div class="grid">${list.map(card).join('')}</div></div>`;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;renderCatalog()});document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>book(state.units.find(u=>u.id===b.dataset.book)))}
function book(u){const today=new Date();today.setDate(today.getDate()+1);const start=today.toISOString().slice(0,10);today.setDate(today.getDate()+2);const end=today.toISOString().slice(0,10);$('#dialogBody').innerHTML=`<p class="tag">${u.asset_tag} · ${u.location_name}</p><h2>${u.model}</h2><p class="muted">${money(u.daily_rate_cents)} per day · ${money(u.deposit_cents)} refundable deposit</p><form id="bookForm" class="stack"><div class="row"><div class="field"><label>Start day</label><input name="start_date" type="date" value="${start}" required></div><div class="field"><label>Return day</label><input name="end_date" type="date" value="${end}" required></div></div><button class="btn dark" type="submit">Get live price</button></form><div id="quote"></div>`;$('#dialog').showModal();$('#bookForm').onsubmit=async e=>{e.preventDefault();const body={unit_id:u.id,...Object.fromEntries(new FormData(e.target))};try{const d=await api('/api/quotes',{method:'POST',body:JSON.stringify(body)});const q=d.quote;$('#quote').innerHTML=`<div class="panel"><div class="row between"><b>${q.day_count} calendar day${q.day_count>1?'s':''}</b><span class="total">${money(q.total_cents)}</span></div><div class="breakdown"><div><span>Kit hire</span><b>${money(q.rental_cents)}</b></div>${q.discount_cents?`<div><span>7+ day saving</span><b>−${money(q.discount_cents)}</b></div>`:''}<div><span>Weekend line</span><b>${money(q.weekend_cents)}</b></div><div><span>County tax</span><b>${money(q.tax_cents)}</b></div><div><span>Hull insurance</span><b>${money(q.hull_cents)}</b></div><div><span>Refundable deposit</span><b>${money(q.deposit_cents)}</b></div></div><button class="btn" id="pay">Continue to secure Stripe Checkout</button><p class="muted">Dates are held only after Stripe confirms payment.</p></div>`;$('#pay').onclick=async()=>{try{const x=await api('/api/checkout',{method:'POST',body:JSON.stringify(body)});location.href=x.checkout_url}catch(err){flash(err.message,true)}}}catch(err){$('#quote').innerHTML=`<div class="role-banner">${err.message}</div>`}}}
async function showRecords(){try{const d=await api('/api/me/records');$('#content').innerHTML=`<div class="section" id="records"><div class="section-head"><div><p class="eyebrow" style="color:var(--rust)">YOUR GEARVAULT FILE</p><h2>Rentals & records</h2><p>Only records belonging to ${state.me.full_name} are shown.</p></div><button class="btn ghost" id="back">Back to catalog</button></div><div class="two-col"><div class="panel"><h3>Reservations</h3>${d.reservations.length?d.reservations.map(r=>`<div class="record"><div><h4>${r.asset_tag} · ${r.model}</h4><div class="muted">${fmtDate(r.start_date)} — ${fmtDate(r.end_date)} · ${r.location_name}</div><div>${status(r.status)} · Total ${money(r.total_cents)} · Deposit ${money(r.deposit_cents)}</div></div><div class="stack"><a class="btn ghost" href="/downloads/hire-waiver.pdf">Hire waiver PDF</a><button class="btn ghost" data-cal="${r.id}">Add to calendar</button>${r.status==='PAID'?`<button class="btn danger" data-cancel="${r.id}">Cancel rental</button>`:''}</div></div>`).join(''):'<div class="empty">No paid rentals yet. Unpaid checkouts never appear here.</div>'}</div><div><div class="panel"><h3>Operator cards</h3>${d.certifications.length?d.certifications.map(c=>`<p><b>${c.certification_type}</b><br><span class="muted">Valid through ${fmtDate(c.expires_on)}</span></p>`).join(''):'<p class="muted">No certifications on file.</p>'}</div><div class="panel"><h3>Delivery trail</h3><p><b>${(d.receipts||[]).length}</b> paper copies</p><p><b>${(d.receipts||[]).length}</b> texts · <b>${(d.receipts||[]).length}</b> emails</p><p><b>${(d.holds||[]).length}</b> diary holds · <b>${(d.punches||[]).length}</b> loyalty punches</p></div></div></div></div>`;$('#back').onclick=renderCatalog;document.querySelectorAll('[data-cal]').forEach(b=>b.onclick=async()=>{const r=await fetch(`/api/reservations/${b.dataset.cal}/calendar.ics`,{headers:{'X-Demo-User':user()}});if(!r.ok)return flash((await r.json()).error,true);const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='GearVault-hire.ics';a.click()});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(confirm('Cancel this paid rental before pickup?'))try{const x=await api(`/api/reservations/${b.dataset.cancel}/cancel`,{method:'POST',body:'{}'});flash(x.message);showRecords();await load()}catch(e){flash(e.message,true)}})}catch(e){flash(e.message,true)}}
